    $saved=all('SELECT * FROM '.table('settings')." WHERE name IN ('license_schema_version','license_invoice_cutover','license_upgrade_pending') ORDER BY name");
    $rename=[];$restore=[];foreach($names as $n){$rename[]='`'.$prefix.$n.'` TO `'.$prefix.'held_'.$n.'`';$restore[]='`'.$prefix.'held_'.$n.'` TO `'.$prefix.$n.'`';}
    db()->exec('RENAME TABLE '.implode(', ',$rename));
    try{
        query('DELETE FROM '.table('settings')." WHERE name IN ('license_schema_version','license_invoice_cutover'".($keepPending?')':",'license_upgrade_pending')"));
        $settings=all('SELECT * FROM '.table('settings').' ORDER BY name');$audit=all('SELECT * FROM '.table('audit').' ORDER BY id');$tables=all('SHOW TABLES');
        lic_ok('Missing licensing family fixture genuinely removes all tables and selected markers '.($keepPending?'pending-retained':'all-markers'),!array_filter($names,fn($n)=>one('SELECT TABLE_NAME FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?',[$prefix.$n]))&&one('SELECT value FROM '.table('settings').' WHERE name=?',['license_schema_version'])===null&&one('SELECT value FROM '.table('settings').' WHERE name=?',['license_invoice_cutover'])===null&&(($pending=one('SELECT value FROM '.table('settings').' WHERE name=?',['license_upgrade_pending']))!==null)===$keepPending);
        global $password;lu_deny('Lost family with retained audit refuses '.($keepPending?'completed-fresh-pending':'all-markers'),fn()=>license_migrate($password),'Licensing audit history needs recovery. Existing records were not recreated.');
        lic_ok('Lost family refusal preserves physical tables settings and audit '.($keepPending?'pending-retained':'all-markers'),all('SHOW TABLES')===$tables&&all('SELECT * FROM '.table('settings').' ORDER BY name')===$settings&&all('SELECT * FROM '.table('audit').' ORDER BY id')===$audit);
    }finally{
        db()->exec('RENAME TABLE '.implode(', ',$restore));
        foreach($saved as $row)query('INSERT INTO '.table('settings').' (name,value) VALUES (?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$row['name'],$row['value']]);
        unset($GLOBALS['cwp_settings']);
    }
    lic_ok('Lost family fixture restores every original row and marker '.($keepPending?'pending-retained':'all-markers'),lu_state()===$before);
}
